(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-381":{scenario:{company:"Polaris Insight Research",supervisor:{name:"Hà Thanh Tâm",role:{vi:"Giám đốc Nghiên cứu",en:"Research Director"}},ref_code:"MR-2048",title:{vi:"Mẫu nào, kết luận nấy. Gia quyền trước khi kết luận.",en:"Know your sample. Weight before you conclude."},brief:{vi:"Bạn kiểm tra báo cáo kiểm định concept MR-2048 cho dòng sữa hạt mới. Mẫu 500 người lấy từ panel trực tuyến, chỉ đặt hạn ngạch theo giới và tuổi; mẫu có 350 người thành thị và 150 nông thôn, trong khi tổng thể mục tiêu là 40% thành thị, 60% nông thôn. Ý định mua (top-2-box): thành thị 50%, nông thôn 30%. Bản nháp ghi mẫu SRS, sai số ±4,4% và ý định mua 44%. Sửa loại mẫu và ý định mua có gia quyền (%), rồi lập báo cáo có căn cứ.",en:"You are checking concept test report MR-2048 for a new nut milk line. The 500 respondents came from an online panel with quotas on gender and age only; the sample has 350 urban and 150 rural respondents, while the target population is 40% urban and 60% rural. Purchase intent (top-2-box): urban 50%, rural 30%. The draft states an SRS sample, a +/-4.4% margin of error and 44% intent. Correct the sample type and the weighted intent (%), then write an evidence-based report."},reference_title:{vi:"Thiết kế mẫu & bảng gia quyền đã duyệt · MR-2048",en:"Approved sample design & weighting sheet · MR-2048"},fields:[{id:"SAMPLE_TYPE",label:{vi:"Loại mẫu trong phần phương pháp",en:"Sample type in methodology"},initial:"SRS",expected:"QUOTA",choices:["SRS","QUOTA","CLUSTER"],reference:"Thiết kế mẫu nghiên cứu",hint:{vi:"Panel trực tuyến tự nguyện có hạn ngạch là mẫu phi xác suất; không được trình bày như mẫu ngẫu nhiên đơn giản.",en:"A volunteer online panel with quotas is a non-probability sample; it must not be presented as simple random."}},{id:"INTENT_W",label:{vi:"Ý định mua có gia quyền (%)",en:"Weighted purchase intent (%)"},initial:"44",expected:"38",reference:"Bảng gia quyền theo khu vực",ref_value:{vi:"Thành thị: ý định 50%, tổng thể 40%; nông thôn: ý định 30%, tổng thể 60%",en:"Urban: intent 50%, population 40%; rural: intent 30%, population 60%"},hint:{vi:"Con số 44% là trung bình theo cơ cấu mẫu lệch; hãy dùng tỷ trọng của tổng thể mục tiêu.",en:"The 44% figure follows the skewed sample mix; use the target population shares instead."}}],sop32:{vi:"Khi cơ cấu mẫu lệch tổng thể, gia quyền hậu phân tầng: chỉ số = tổng (tỷ trọng tổng thể của nhóm x tỷ lệ của nhóm). Không công bố sai số chọn mẫu kiểu ngẫu nhiên cho mẫu phi xác suất.",en:"When the sample mix differs from the population, post-stratify: estimate = sum (group population share x group rate). Never publish random-sampling margins of error for non-probability samples."},context:{label:"SURVEY DATA / MR-2048",metrics:[{label:{vi:"Cỡ mẫu",en:"Sample size"},value:"500 (350 / 150)"},{label:{vi:"Tổng thể thành thị / nông thôn",en:"Population urban / rural"},value:"40% / 60%"},{label:{vi:"Chuẩn hành động ra mắt",en:"Launch action standard"},value:">= 40%"}]},crisis:{vi:"Quản lý thương hiệu của khách hàng nhắn: “Chuẩn ra mắt là 40%. Cứ báo con số 44% chưa gia quyền, hoặc bỏ bớt mẫu nông thôn đi, ban giám đốc chỉ cần thấy concept đạt chuẩn.”",en:"The client's brand manager messages you: “The launch standard is 40%. Just report the unweighted 44%, or drop some rural respondents, the board only needs to see the concept pass.”"},options:{safe:{vi:"Báo cáo 38% có gia quyền kèm ghi chú phương pháp, báo Giám đốc Nghiên cứu; đề xuất tối ưu concept và kiểm định lại với mẫu nông thôn tăng cường thay vì chỉnh dữ liệu.",en:"Report the weighted 38% with a methodology note and inform the Research Director; propose optimizing the concept and retesting with a rural boost instead of altering data."},shortcut:{vi:"Báo con số 44% chưa gia quyền vì khách hàng là người trả tiền dự án.",en:"Report the unweighted 44% because the client pays for the project."},wait:{vi:"Gửi bảng số liệu thô cho khách tự chọn con số muốn trình bày.",en:"Send the raw tables and let the client pick the number to present."}},questions:{vi:["Vì sao loại mẫu phải ghi QUOTA và không được công bố sai số ±4,4%? Hãy giải thích bằng cách tuyển mẫu.","Trình bày cách tính ý định mua 38% có gia quyền và hệ quả nếu dùng con số 44% để quyết định ra mắt."],en:["Why must the sample type read QUOTA and why can the +/-4.4% margin not be published? Explain using the recruitment method.","Explain how you reached the weighted 38% intent and the consequences of using 44% for the launch decision."]},hints:{vi:["Đọc lại cách tuyển mẫu: nguồn panel, cách đặt hạn ngạch và mỗi người có xác suất được chọn biết trước hay không.","Theo SOP mục 3.2, nhân tỷ lệ của từng khu vực với tỷ trọng tổng thể rồi cộng lại.","Đọc SOP mục 4.2: kết quả nghiên cứu phải phản ánh đúng dữ liệu, không chỉnh để phục vụ quyết định định trước."],en:["Re-read the recruitment: panel source, quota setting and whether each person had a known selection probability.","Per SOP 3.2, multiply each area's rate by its population share and add them up.","Read SOP 4.2: research findings must reflect the data, never be tuned to fit a decision made in advance."]}},learning:{summary:{vi:"Chuyên viên Nghiên cứu thị trường & Thấu hiểu khách hàng thiết kế và phân tích nghiên cứu định lượng, định tính để trả lời câu hỏi kinh doanh: ai là khách hàng, họ cần gì, vì sao họ chọn hay rời bỏ thương hiệu, concept nào nên ra mắt. Nghề đòi hỏi nền tảng thống kê, thiết kế mẫu và bảng hỏi không thiên lệch, kỹ năng kể chuyện từ dữ liệu và chuẩn mực đạo đức nghiên cứu nghiêm ngặt.",en:"A Market Research & Consumer Insights Analyst designs and analyzes quantitative and qualitative studies that answer business questions: who the customers are, what they need, why they choose or leave a brand and which concept should launch. The role requires statistical grounding, unbiased sample and questionnaire design, data storytelling and strict research ethics."},responsibilities:{vi:["Chuyển câu hỏi kinh doanh thành mục tiêu, giả thuyết và thiết kế nghiên cứu phù hợp.","Thiết kế mẫu, hạn ngạch, bảng hỏi và hướng dẫn thảo luận nhóm, phỏng vấn sâu.","Kiểm soát chất lượng dữ liệu: loại bản trả lời kém chất lượng, kiểm tra logic, gia quyền.","Phân tích thống kê, kiểm định khác biệt, phân khúc và tổng hợp phát hiện định tính.","Viết báo cáo thấu hiểu, đề xuất hành động và trình bày cho các bên liên quan."],en:["Turn business questions into objectives, hypotheses and the right research design.","Design samples, quotas, questionnaires and discussion or interview guides.","Control data quality: remove poor responses, run logic checks and apply weights.","Run statistical analysis, significance tests, segmentation and qualitative synthesis.","Write insight reports, recommend actions and present to stakeholders."]},competencies:[{name:{vi:"Thiết kế mẫu & thống kê",en:"Sampling & statistics"},desc:{vi:"Phân biệt mẫu xác suất và phi xác suất, tính sai số, hiệu ứng thiết kế và gia quyền đúng cách.",en:"Separate probability and non-probability samples and compute margins, design effects and weights correctly."}},{name:{vi:"Thiết kế bảng hỏi",en:"Questionnaire design"},desc:{vi:"Viết câu hỏi trung lập, thang đo phù hợp, tránh câu dẫn dắt và câu hỏi kép.",en:"Write neutral questions with fitting scales and avoid leading or double-barreled items."}},{name:{vi:"Nghiên cứu định tính",en:"Qualitative research"},desc:{vi:"Điều phối thảo luận nhóm, phỏng vấn sâu, quan sát và phân tích chủ đề có hệ thống.",en:"Moderate focus groups and in-depth interviews, observe and run systematic thematic analysis."}},{name:{vi:"Kể chuyện bằng dữ liệu",en:"Data storytelling"},desc:{vi:"Biến bảng số thành thông điệp rõ ràng, ưu tiên điều ảnh hưởng tới quyết định kinh doanh.",en:"Turn tables into clear messages that put decision-relevant findings first."}},{name:{vi:"Đạo đức nghiên cứu",en:"Research ethics"},desc:{vi:"Bảo vệ người trả lời, minh bạch phương pháp và từ chối chỉnh kết quả theo ý khách hàng.",en:"Protect respondents, disclose methods transparently and refuse to bend results for clients."}}],knowledge:{vi:["Bộ quy tắc quốc tế ICC/ESOMAR về nghiên cứu thị trường, xã hội và phân tích dữ liệu.","ISO 20252 về yêu cầu dịch vụ nghiên cứu thị trường, ý kiến và xã hội.","Lý thuyết chọn mẫu: mẫu xác suất, mẫu hạn ngạch, sai số chọn mẫu = z x căn(p(1 - p) / n), hiệu ứng thiết kế.","Gia quyền hậu phân tầng, gia quyền RIM và cỡ mẫu hiệu dụng.","Kiểm định thống kê: chi bình phương, t-test, ý nghĩa thống kê và cỡ mẫu tối thiểu khi đọc nhóm nhỏ.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân của người tham gia khảo sát."],en:["The ICC/ESOMAR International Code on market, opinion and social research and data analytics.","ISO 20252 service requirements for market, opinion and social research.","Sampling theory: probability samples, quota samples, margin of error = z x sqrt(p(1 - p) / n), design effect.","Post-stratification, RIM weighting and effective sample size.","Statistical tests: chi-square, t-test, significance and minimum bases for small subgroups.","Decree 13/2023/ND-CP on protecting survey participants' personal data."]},tools:["SPSS / R / Python","Nền tảng khảo sát trực tuyến","Online panel","Phần mềm mã hóa dữ liệu định tính","Microsoft Excel / PowerPoint","Power BI / Tableau"],kpis:{vi:["Tỷ lệ dự án giao đúng hạn với dữ liệu đạt kiểm soát chất lượng.","Tỷ lệ khuyến nghị nghiên cứu được kinh doanh áp dụng.","Số lỗi phương pháp hoặc số liệu bị phát hiện sau khi phát hành (mục tiêu bằng 0).","Mức hài lòng của bên đặt hàng nghiên cứu."],en:["Share of projects delivered on time with data passing quality control.","Share of research recommendations adopted by the business.","Method or data errors found after release (target zero).","Satisfaction of research stakeholders."]},day:[{time:"08:30",vi:"Kiểm tra tiến độ thu mẫu, tỷ lệ đạt hạn ngạch và bản trả lời đáng ngờ.",en:"Check fieldwork progress, quota fill and suspicious responses."},{time:"10:00",vi:"Làm sạch dữ liệu, chạy bảng chéo và tính trọng số theo tổng thể mục tiêu.",en:"Clean data, run cross-tabs and compute weights against the target population."},{time:"13:30",vi:"Điều phối một buổi thảo luận nhóm về thói quen dùng sữa hạt.",en:"Moderate a focus group on nut milk habits."},{time:"15:30",vi:"Kiểm định khác biệt giữa các phân khúc và ghi chú cỡ mẫu nhỏ.",en:"Test differences between segments and flag small bases."},{time:"17:00",vi:"Viết phần tóm tắt thấu hiểu và đề xuất hành động cho báo cáo.",en:"Draft the insight summary and recommended actions for the report."}],mistakes:{vi:["Công bố sai số kiểu ngẫu nhiên cho mẫu panel trực tuyến phi xác suất.","Báo cáo số liệu chưa gia quyền khi cơ cấu mẫu lệch xa tổng thể.","Đặt câu hỏi dẫn dắt hoặc đọc kết luận từ nhóm có cỡ mẫu quá nhỏ."],en:["Publishing random-sampling margins of error for non-probability online panels.","Reporting unweighted figures when the sample mix is far from the population.","Asking leading questions or drawing conclusions from tiny subgroups."]},career:[{vi:"Nhân viên phân tích dữ liệu khảo sát",en:"Research Executive"},{vi:"Chuyên viên Nghiên cứu thị trường & Thấu hiểu khách hàng",en:"Market Research & Consumer Insights Analyst"},{vi:"Quản lý nghiên cứu / Quản lý thấu hiểu khách hàng",en:"Research Manager / Insights Manager"},{vi:"Giám đốc Nghiên cứu & Thấu hiểu khách hàng",en:"Head of Research & Consumer Insights"}],glossary:[{term:"Quota sampling",vi:"Chọn mẫu phi xác suất, tuyển người trả lời đến khi đủ số lượng định trước cho từng nhóm.",en:"Non-probability sampling that recruits until preset counts per group are filled."},{term:"Weighting",vi:"Điều chỉnh trọng số người trả lời để cơ cấu mẫu khớp với tổng thể mục tiêu.",en:"Adjusting respondent weights so the sample mix matches the target population."},{term:"Top-2-box",vi:"Tỷ lệ chọn hai mức cao nhất của thang đo, ví dụ chắc chắn mua và có thể mua.",en:"Share choosing the two highest scale points, such as definitely and probably buy."},{term:"Margin of error",vi:"Biên sai số chọn mẫu ở độ tin cậy nhất định, chỉ có ý nghĩa đầy đủ với mẫu xác suất.",en:"Sampling error band at a given confidence level, fully meaningful only for probability samples."},{term:"Action standard",vi:"Ngưỡng kết quả được thống nhất trước nghiên cứu để ra quyết định kinh doanh.",en:"A result threshold agreed before the study to drive a business decision."}],quiz:[{q:{vi:"Tổng thể 30% nhóm A, 70% nhóm B. Tỷ lệ thích sản phẩm: A 60%, B 40%. Chỉ số có gia quyền là bao nhiêu?",en:"The population is 30% group A and 70% group B. Product liking: A 60%, B 40%. What is the weighted figure?"},options:{vi:["50%","46%","54%","40%"],en:["50%","46%","54%","40%"]},answer:1,explain:{vi:"Chỉ số có gia quyền = 0,3 x 60 + 0,7 x 40 = 18 + 28 = 46%; trung bình cộng 50% là sai.",en:"0.3 x 60 + 0.7 x 40 = 18 + 28 = 46%."}},{q:{vi:"Câu hỏi nào là câu hỏi dẫn dắt?",en:"Which question is leading?"},options:{vi:["Bạn thường mua sữa ở đâu?","Bạn uống sữa bao nhiêu lần mỗi tuần?","Bạn đánh giá vị sản phẩm thế nào trên thang 1-5?","Bạn có đồng ý sản phẩm tuyệt vời này đáng mua không?"],en:["Where do you usually buy milk?","How many times a week do you drink milk?","How do you rate the taste on a 1-5 scale?","Do you agree this great product is worth buying?"]},answer:3,explain:{vi:"Từ “tuyệt vời” và cấu trúc “có đồng ý” gợi ý câu trả lời, làm kết quả thiên lệch.",en:"The word great and the agree framing suggest the answer and bias results."}},{q:{vi:"Mẫu ngẫu nhiên đơn giản n = 400, p = 0,5, độ tin cậy 95%. Sai số chọn mẫu xấp xỉ bao nhiêu?",en:"A simple random sample n = 400, p = 0.5, 95% confidence. What is the approximate margin of error?"},options:{vi:["±4,9%","±2,5%","±10%","±1,0%"],en:["+/-4.9%","+/-2.5%","+/-10%","+/-1.0%"]},answer:0,explain:{vi:"1,96 x căn(0,25 / 400) = 1,96 x 0,025 ≈ 4,9%.",en:"1.96 x sqrt(0.25 / 400) = 1.96 x 0.025 = about 4.9%."}},{q:{vi:"Khách hàng đề nghị bỏ bớt người trả lời nông thôn để concept vượt chuẩn ra mắt. Bạn làm gì?",en:"The client asks to drop rural respondents so the concept clears the launch standard. What do you do?"},options:{vi:["Bỏ một phần cho cân đối","Làm theo vì khách trả tiền","Từ chối, báo cáo đúng số gia quyền và đề xuất nghiên cứu bổ sung","Ghi cả hai con số và để khách chọn"],en:["Drop some for balance","Comply because the client pays","Refuse, report the correct weighted figure and propose follow-up research","Show both numbers and let the client pick"]},answer:2,explain:{vi:"Chỉnh dữ liệu theo kết luận mong muốn vi phạm chuẩn mực nghề; phải minh bạch và đề xuất phương án hợp lệ.",en:"Bending data to a desired conclusion breaches professional codes; stay transparent and propose valid options."}}],tools_en:["SPSS / R / Python","Online survey platforms","Online panel","Qualitative data coding software","Microsoft Excel / PowerPoint","Power BI / Tableau"]}}})})(window.KKR);
